# Writes the JS spec and its TypeScript types from the R specs.
#
#   Rscript dev/gen-spec.R
#
# For every `*_SPEC` object in the package namespace, writes
# inst/js/spec/<block>.js (the spec as data, at Blockr.viz.spec.<block>) and
# inst/js/spec/<block>.d.ts (the block's config and settings message types).
# The files are checked in; tests/testthat/test-gen-spec.R fails when they
# differ from what this script writes.

gen_spec_header <- function(block) {
  paste0("// Generated by dev/gen-spec.R from the R spec of the ", block,
         " block. Do not edit.")
}

# The spec as plain data for the browser: what the gear and the type checks
# need. The registry text (`describe`, `example`, `ai`) stays in R.
gen_spec_data <- function(spec) {
  lapply(spec$args, gen_arg_data)
}

gen_arg_data <- function(a) {
  d <- a$default
  out <- list(
    type = gen_type_data(a$type),
    default = if (inherits(d, "viz_opt")) NULL else gen_default(a$type, d),
    option = if (inherits(d, "viz_opt")) d$name,
    values = if (!is.null(a$values)) I(a$values),
    bounds = if (!is.null(a$bounds)) {
      list(min = gen_num(a$bounds$min), max = gen_num(a$bounds$max),
           minOpen = a$bounds$min_open)
    },
    nullable = !isFALSE(a$null),
    required = if (isTRUE(a$required)) TRUE,
    also = if (!is.null(a$also)) I(a$also),
    applies = gen_applies(a$applies),
    gear = if (!is.null(a$gear)) gen_gear(a$gear),
    slot = a$slot,
    ctrl = a$ctrl
  )
  Filter(Negate(is.null), out)
}

gen_type_data <- function(type) {
  out <- list(name = type$name, of = type$of, key = type$key)
  if (!is.null(type$fields)) out$fields <- lapply(type$fields, gen_arg_data)
  if (!is.null(type$value)) out$value <- gen_arg_data(type$value)
  if (!is.null(type$max)) out$max <- type$max
  if (!is.null(type$variants)) {
    out$variants <- lapply(type$variants, function(v) {
      lapply(v$fields, gen_arg_data)
    })
  }
  Filter(Negate(is.null), out)
}

# A default as viz_wire() would send it.
gen_default <- function(type, d) {
  if (is.null(d)) {
    return(NULL)
  }
  jsonlite::fromJSON(wire_json(list(x = wire_value(type, d))),
                     simplifyVector = FALSE)$x
}

gen_num <- function(x) if (is.finite(x)) x else NULL

gen_applies <- function(a) {
  if (is.null(a)) {
    return(NULL)
  }
  if (inherits(a, "viz_except")) {
    return(list(except = I(unclass(a))))
  }
  list(only = I(a))
}

gen_gear <- function(g) {
  out <- list(group = g$group, control = g$control, label = g$label,
              labels = if (!is.null(g$labels)) I(g$labels), parse = g$parse,
              when = g$when)
  Filter(Negate(is.null), out)
}

gen_spec_js <- function(spec) {
  json <- jsonlite::toJSON(gen_spec_data(spec), auto_unbox = TRUE,
                           pretty = 2, null = "null", digits = NA)
  c(
    gen_spec_header(spec$block),
    "// @ts-check",
    "(function () {",
    "  'use strict';",
    "  const root = /** @type {any} */ (typeof window !== 'undefined' ? window : globalThis);",
    "  const B = /** @type {any} */ (root.Blockr = root.Blockr || {});",
    "  const V = /** @type {any} */ (B.viz = B.viz || {});",
    "  V.spec = V.spec || {};",
    paste0("  V.spec.", spec$block, " = ",
           gsub("\n", "\n  ", json, fixed = TRUE), ";"),
    "})();"
  )
}

# The TypeScript type of a value as viz_wire() sends it.
gen_ts_type <- function(type, values = NULL, nullable = FALSE) {
  lit <- function(v) paste0("'", v, "'", collapse = " | ")
  t <- switch(
    type$name,
    column = , string = , template = "string",
    columns = , strings = "string[]",
    enum = lit(values),
    enums = paste0("(", lit(values), ")[]"),
    number = , integer = "number",
    bool = "boolean",
    numbers = "{ value: number; label: string | null }[]",
    values = "{ value: number | string; label: string | null }[]",
    format = "'number' | 'compact' | 'percent' | number",
    record = gen_ts_record(type$fields),
    records = paste0(gen_ts_record(type$fields), "[]"),
    records_by = gen_ts_variants(type),
    named = paste0("Record<string, ",
                   gen_ts_type(type$value$type, type$value$values,
                               nullable = !isFALSE(type$value$null)), ">"),
    map = "Record<string, unknown>"
  )
  if (nullable) paste(t, "| null") else t
}

gen_ts_record <- function(fields, key = NULL) {
  types <- vapply(names(fields), function(f) {
    a <- fields[[f]]
    paste0(f, ": ", gen_ts_type(a$type, a$values, nullable = !isFALSE(a$null)))
  }, character(1L))
  paste0("{ ", paste(c(key, types), collapse = "; "), " }")
}

# A list of records keyed by `key`: one record type per variant.
gen_ts_variants <- function(type) {
  parts <- vapply(names(type$variants), function(k) {
    fields <- type$variants[[k]]$fields
    gen_ts_record(fields[setdiff(names(fields), type$key)],
                  key = paste0(type$key, ": '", k, "'"))
  }, character(1L))
  paste0("(", paste(parts, collapse = " | "), ")[]")
}

gen_spec_dts <- function(spec) {
  name <- paste0(toupper(substring(spec$block, 1, 1)), substring(spec$block, 2))
  fields <- vapply(names(spec$args), function(nm) {
    a <- spec$args[[nm]]
    paste0("  ", nm, ": ", gen_ts_type(a$type, a$values,
                                       nullable = !isFALSE(a$null)), ";")
  }, character(1L))
  c(
    gen_spec_header(spec$block),
    "",
    paste0("/** The ", spec$block, " block's settings, as viz_wire() sends them. */"),
    paste0("interface ", name, "Config {"),
    fields,
    "}",
    "",
    "/** The settings message: the keys that changed, and the revision the",
    " *  gear was showing when they changed. */",
    paste0("interface ", name, "SetMsg {"),
    "  rev: number;",
    paste0("  values: Partial<", name, "Config>;"),
    "}"
  )
}

# Writes both files for every spec; returns the paths, invisibly.
gen_spec_files <- function(specs, dir) {
  dir.create(dir, showWarnings = FALSE, recursive = TRUE)
  paths <- character()
  for (spec in specs) {
    js <- file.path(dir, paste0(spec$block, ".js"))
    dts <- file.path(dir, paste0(spec$block, ".d.ts"))
    writeLines(gen_spec_js(spec), js)
    writeLines(gen_spec_dts(spec), dts)
    paths <- c(paths, js, dts)
  }
  invisible(paths)
}

# The package's block specs: those in VIZ_BLOCK_SPECS whose spec function
# is defined.
gen_package_specs <- function(ns) {
  blocks <- names(ns$VIZ_BLOCK_SPECS)
  have <- vapply(paste0(blocks, "_spec"), exists, logical(1L), envir = ns,
                 inherits = FALSE)
  lapply(blocks[have], ns$viz_block_spec)
}

if (sys.nframe() == 0L) {
  pkgload::load_all(".", quiet = TRUE)
  specs <- gen_package_specs(asNamespace("blockr.viz"))
  writeLines(gen_spec_files(specs, file.path("inst", "js", "spec")))
}
